-- Existing accounts start with the watchlist they had before (BBCA, BBRI).
INSERT INTO "stock_watchlist" ("user_id", "symbol", "name", "sort_order")
SELECT u."id", s."symbol", s."name", s."sort_order"
FROM "user" u
CROSS JOIN (VALUES ('BBCA', 'Bank Central Asia', 0), ('BBRI', 'Bank Rakyat Indonesia', 1)) AS s("symbol", "name", "sort_order")
ON CONFLICT DO NOTHING;
